nextflow_process {
    name "Test Process GCTA_BIVARIATEREML"
    script "../main.nf"
    process "GCTA_BIVARIATEREML"

    tag "modules"
    tag "modules_nfcore"
    tag "gcta"
    tag "gcta/bivariatereml"
    tag "gcta/makegrm"
    tag "gawk"
    config "./nextflow.config"

    setup {
        run("GAWK", alias: "GAWK_BIVARIATE_PHENO") {
            script "../../../gawk/main.nf"
            process {
                """
                input[0] = [
                    [ id:'Trait1__Trait2' ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/plink_simulated_quantitative_phenoname.phe', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/plink_simulated_covariates.txt', checkIfExists: true)
                    ],
                    "",
                ]
                input[1] = Channel.of('FNR == NR { if (FNR == 1) next; trait1[\$2] = \$3; next } FNR == 1 { next } { print \$1, \$2, trait1[\$2], \$4 }').collectFile(name:'bivariate_phenotype.awk')
                input[2] = false
                """
            }
        }

        run("GAWK", alias: "GAWK_BIVARIATE_BINARY_PHENO") {
            script "../../../gawk/main.nf"
            process {
                """
                input[0] = [
                    [ id:'BinaryTrait1__BinaryTrait2' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/plink_simulated_quantitative_phenoname.phe', checkIfExists: true),
                    "",
                ]
                input[1] = Channel.of('FNR == 1 { next } { print \$1, \$2, (NR % 2) + 1, (NR % 3 == 0 ? 2 : 1) }').collectFile(name:'bivariate_binary_phenotype.awk')
                input[2] = false
                """
            }
        }

        run("GAWK", alias: "GAWK_QUANTITATIVE_COVARIATES") {
            script "../../../gawk/main.nf"
            process {
                """
                input[0] = [
                    [ id:'covariates_quant' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/plink_simulated_covariates.txt', checkIfExists: true),
                    "",
                ]
                input[1] = Channel.of('FNR == 1 { next } { print \$1, \$2, \$5, \$6 }').collectFile(name:'quantitative_covariates.awk')
                input[2] = false
                """
            }
        }

        run("GAWK", alias: "GAWK_CATEGORICAL_COVARIATES") {
            script "../../../gawk/main.nf"
            process {
                """
                input[0] = [
                    [ id:'covariates_cat' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/plink_simulated_covariates.txt', checkIfExists: true),
                    "",
                ]
                input[1] = Channel.of('FNR == 1 { next } { print \$1, \$2, \$3 }').collectFile(name:'categorical_covariates.awk')
                input[2] = false
                """
            }
        }

        run("GCTA_MAKEGRM", alias: "GCTA_MAKEGRM_DENSE") {
            script "../../makegrm/main.nf"
            process {
                """
                file('plink_simulated.mbfile').text = 'plink_simulated\\n'

                input[0] = [
                    [ id:'plink_simulated_dense' ],
                    file('plink_simulated.mbfile'),
                    [
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/plink_simulated.bed', checkIfExists: true)
                    ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/plink_simulated.bim', checkIfExists: true)
                    ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/plink_simulated.fam', checkIfExists: true)
                    ]
                ]
                """
            }
        }
    }

    test("homo_sapiens popgen - bivariate phenotype with dense GRM and covariates") {
        when {
            process {
                """
                input[0] = GCTA_MAKEGRM_DENSE.out.grm_files
                input[1] = GAWK_BIVARIATE_PHENO.out.output.map { meta, phenotype_file -> [[ id:'plink_simulated_dense' ], phenotype_file, 1, 2] }
                input[2] = GAWK_QUANTITATIVE_COVARIATES.out.output.map { meta, quant_covariates_file -> [[ id:'plink_simulated_dense' ], quant_covariates_file] }
                input[3] = GAWK_CATEGORICAL_COVARIATES.out.output.map { meta, cat_covariates_file -> [[ id:'plink_simulated_dense' ], cat_covariates_file] }
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert process.out.bivariate_results.size() == 1 },
                { assert process.out.log_file.size() == 1 },
                { assert process.out.bivariate_results.get(0).get(0).id == "plink_simulated_dense" },
                { assert file(process.out.bivariate_results.get(0).get(1)).name == "plink_simulated_dense.hsq" },
                { assert file(process.out.log_file.get(0).get(1)).name == "plink_simulated_dense.log" },
                { assert file(process.out.log_file.get(0).get(1)).exists() },
                { assert snapshot(sanitizeOutput(process.out, unstableKeys: ["log_file"])).match() }
            )
        }
    }

    test("homo_sapiens popgen - bivariate phenotype with dense GRM and no covariates") {
        when {
            process {
                """
                input[0] = GCTA_MAKEGRM_DENSE.out.grm_files
                input[1] = GAWK_BIVARIATE_PHENO.out.output.map { meta, phenotype_file -> [[ id:'plink_simulated_dense' ], phenotype_file, '', ''] }
                input[2] = [[ id:'plink_simulated_dense' ], []]
                input[3] = [[ id:'plink_simulated_dense' ], []]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert process.out.bivariate_results.size() == 1 },
                { assert process.out.log_file.size() == 1 },
                { assert file(process.out.bivariate_results.get(0).get(1)).name == "plink_simulated_dense.hsq" },
                { assert file(process.out.log_file.get(0).get(1)).name == "plink_simulated_dense.log" },
                { assert snapshot(sanitizeOutput(process.out, unstableKeys: ["log_file"])).match() }
            )
        }
    }

    test("homo_sapiens popgen - binary bivariate phenotype with prevalence") {
        when {
            params {
                module_args = '--reml-bivar-prevalence 0.30 0.25'
            }
            process {
                """
                input[0] = GCTA_MAKEGRM_DENSE.out.grm_files
                input[1] = GAWK_BIVARIATE_BINARY_PHENO.out.output.map { meta, phenotype_file -> [[ id:'plink_simulated_dense' ], phenotype_file, '', ''] }
                input[2] = [[ id:'plink_simulated_dense' ], []]
                input[3] = [[ id:'plink_simulated_dense' ], []]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert process.out.bivariate_results.size() == 1 },
                { assert process.out.log_file.size() == 1 },
                { assert process.out.bivariate_results.get(0).get(0).id == "plink_simulated_dense" },
                { assert file(process.out.bivariate_results.get(0).get(1)).name == "plink_simulated_dense.hsq" },
                { assert file(process.out.log_file.get(0).get(1)).name == "plink_simulated_dense.log" },
                {
                    def logText = file(process.out.log_file.get(0).get(1)).text
                    assert logText.contains("--reml-bivar-prevalence 0.3 0.25")
                },
                { assert snapshot(sanitizeOutput(process.out, unstableKeys: ["log_file"])).match() }
            )
        }
    }

    test("homo_sapiens popgen - bivariate phenotype fails when meta.id is not GRM basename") {
        when {
            process {
                """
                mismatched_dense_grm = GCTA_MAKEGRM_DENSE.out.grm_files.map { meta, grm_files ->
                    [[ id:meta.id + '_mismatched' ], grm_files]
                }

                input[0] = mismatched_dense_grm
                input[1] = GAWK_BIVARIATE_PHENO.out.output.map { meta, phenotype_file -> [[ id:'plink_simulated_dense_mismatched' ], phenotype_file, '', ''] }
                input[2] = [[ id:'plink_simulated_dense_mismatched' ], []]
                input[3] = [[ id:'plink_simulated_dense_mismatched' ], []]
                """
            }
        }

        then {
            assertAll(
                { assert !process.success },
                { assert process.exitStatus != 0 }
            )
        }
    }

    test("homo_sapiens popgen - bivariate phenotype with dense GRM - stub") {
        options "-stub"

        when {
            process {
                """
                input[0] = GCTA_MAKEGRM_DENSE.out.grm_files
                input[1] = GAWK_BIVARIATE_PHENO.out.output.map { meta, phenotype_file -> [[ id:'plink_simulated_dense' ], phenotype_file, '', ''] }
                input[2] = [[ id:'plink_simulated_dense' ], []]
                input[3] = [[ id:'plink_simulated_dense' ], []]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert process.out.bivariate_results.get(0).get(0).id == "plink_simulated_dense" },
                { assert file(process.out.bivariate_results.get(0).get(1)).name == "plink_simulated_dense.hsq" },
                { assert file(process.out.log_file.get(0).get(1)).name == "plink_simulated_dense.log" },
                { assert snapshot(sanitizeOutput(process.out, unstableKeys: ["log_file"])).match() }
            )
        }
    }
}

